  /* Минимальный кегль текста интерфейса. Apple HIG Typography: самый мелкий
     стиль tvOS — Caption 2, 23 px, и «дефолт 29 px, минимум 23»; Amazon даёт
     28 px телу текста, Microsoft — 30 основному и 24 второстепенному
     (docs/research/2026-09-21-tv-design-specs.md §1 и §2). 23 физических px
     при базе Lampa 22.811 — это 1.01em, и это ФИЗИЧЕСКИЕ пиксели растра: на
     Philips 50PUS8057 WebView отдаёт CSS-окно 960×540 при devicePixelRatio 2,
     то есть 1.01em = 11.5 CSS px и те же 23 px на панели.
     Число живёт здесь, а не литералами в правилах: тест
     «Task 63: ни один текст интерфейса не мельче минимума tvOS» читает все
     font-size собранной таблицы и сверяется с ним же. */
  var TV_MIN = 1.01;

  /* Размер героя — настройка (правка пользователя 2026-09-17, п.2).

     Task 36: три размера задают ДВЕ доли экрана каждый — сколько кадр
     занимает в стартовом состоянии (HERO_VH) и где проходит его нижняя
     кромка в сжатом (ROWS_TOP_VH, оно же место, от которого начинаются
     ряды). Разность этих двух чисел и есть сдвиг сжатия: кадр уезжает под
     шапку Lampa, не меняя высоты.

     Крупный — «две трети экрана в старте, половина в сжатом», как просил
     пользователь на живом телевизоре 2026-09-18 («картинка очень маленькая,
     надо намного больше, половина экрана, если не больше»). Средний и
     компактный — те же два состояния от меньшей базы: 56 → 42 % и
     45 → 34 % экрана.

     Значение 'off' сюда не попадает: при нём герой не монтируется вовсе
     (src/48_hero.js), класса .lumen-main на активности нет, и раскладка
     главной остаётся штатной Lampa. */
