  var HERO_DEFAULT = 'large';

  /* Ряды в СТАРТОВОМ состоянии опущены на эту долю экрана и поднимаются к
     своему месту при листании. Величина одна на все размеры кадра: она не
     «сколько отдал кадр», а «насколько ряд выглядывает снизу» — ровно тот
     приём, которым живёт главная tvOS. Больше сдвига — от ряда остаётся один
     заголовок; меньше — текст героя поднимается вместе с рядом (его отступ
     снизу считается отсюда же, textBottomVh), и внизу кадра остаётся пустая
     полоса. 5.5vh — это 59 px при 1080.

     В старте нижняя часть кадра оказывается ПОД первым рядом: у крупного
     размера кадр кончается на 66.67vh, а заголовок ряда стоит на 55.5vh плюс
     воздух (2.5em штатного padding Lampa и 1em, на который поднят отступ
     области), то есть 58.67vh — примерно в 12 % высоты кадра от его низа.
     Это задумано и безопасно: на такой высоте нижняя вуаль держит около .87
     (стопы .92 на 10 % и .6 на 24 % — veilB в accentRules выше), и картинки
     под заголовком ряда практически не видно.

     Task 51: было 8vh. Сдвиг двигает ряд только в СТАРТОВОМ состоянии (при
     .lumen-rows-up он равен нулю), поэтому подпись в поднятом состоянии от
     него не зависит вовсе — убавлен он ради старта. Замеры на стенде
     координатора 960×540 (CSS px, тест «Task 51: подпись первого ряда…»):
     до правки низ подписи в старте 586 при кромке 540, с новой карточкой и
     прежними 8vh — 555, с 5.5vh — 542. То есть подпись перестала быть
     «срезанной наполовину» и встала ровно на кромку. За кромкой она всё же
     остаётся, и это не приём, а размен: кадр героя занимает две трети
     экрана по прямому требованию пользователя («половина экрана, если не
     больше», живой телевизор 2026-09-18), и на подписи В СТАРТЕ высоты
     экрана после этого не хватает. Читают их в поднятом состоянии, где они
     на экране целиком. Цена правки — textBottomVh: низ текста героя в
     старте поднимается на те же 2.5vh, и оба порога низкого окна (textRatio
     ниже) съезжают пропорционально. */
  var ROWS_SHIFT_VH = 5.5;

  /* Воздух между нижней кромкой СЖАТОГО кадра и заголовком первого ряда
     (пользователь: «вот тут надо отступ, слишком близко к границе»). В em,
     а не в vh: это типографский зазор, он должен расти вместе с кеглем
     заголовка ряда, а не с высотой экрана. */
  var ROWS_AIR = 1.5;

  /* Текст героя. TEXT_AIR_VH — на столько низ текстового блока выше верха
     первого ряда в СТАРТОВОМ состоянии; TEXT_EDGE_VH — на столько он выше
     нижней кромки кадра в сжатом (там ряда над ним нет, и прижимать текст
     вплотную к кромке незачем). Из этих двух величин считаются и отступ
     снизу, и сдвиг сжатия, поэтому текст не может налезть ни на ряд, ни на
     кромку ни при одном размере кадра. */
